Concat_and_Clean_All_Emails.inputs:
@concat(
    if(
        not(empty(variables('AddressFrom'))),
        concat('"', variables('AddressFrom'), '"'),
        ''
    ),
    if(
        not(empty(variables('EmailBody')?['toRecipients'])),
        concat(
            if(
                not(empty(variables('EmailBody')?['from']?['emailAddress']?['address'])),
                ', ',
                ''
            ),
            outputs('Recipient_Address')
        ),
        ''
    ),
    if(
        not(empty(variables('EmailBody')?['ccRecipients'])),
        concat(
            if(
                or(
                    not(empty(variables('EmailBody')?['from']?['emailAddress']?['address'])),
                    not(empty(variables('EmailBody')?['toRecipients']))
                ),
                ', ',
                ''
            ),
            outputs('CC_Address')
        ),
        ''
    ),
    if(
        not(empty(variables('EmailBody')?['bccRecipients'])),
        concat(
            if(
                or(
                    not(empty(variables('EmailBody')?['from']?['emailAddress']?['address'])),
                    not(empty(variables('EmailBody')?['toRecipients'])),
                    not(empty(variables('EmailBody')?['ccRecipients']))
                ),
                ', ',
                ''
            ),
            outputs('BCC_Address')
        ),
        ''
    )
)
